df <- data.frame(x = 1:3, y = I(1:3))
z <- c(3, 5, 4)
value <- tryCatch({
  predictor <- stats::model.frame(z ~ x + y, data = df)$y
  if (is.factor(predictor)) 'factor' else if (is.character(predictor)) 'character' else if (is.numeric(predictor)) 'numeric' else typeof(predictor)
}, error = function(condition) 'error')
option_types <- c(A = 'factor', B = 'character', C = 'numeric', D = 'error')
answer <- names(option_types)[option_types == value]
